package com.fanzuixianchang.ops;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fanzuixianchang.core.Problem;
import java.nio.file.Path;
import java.nio.file.Files;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;
class OpsWorkStoreTest {
 @TempDir Path dir;
 OpsWorkStore store(){return new OpsWorkStore(new ObjectMapper(),dir.toString());}
 @Test void feedbackConsentAndResolutionPersist(){var s=store();assertThrows(Problem.class,()->s.createFeedback(new OpsWorkStore.FeedbackInput("other","feedback",false)));assertTrue(s.feedback().isEmpty());var f=s.createFeedback(new OpsWorkStore.FeedbackInput("recognition","识别成了苹果",true));assertEquals("open",f.status());assertEquals(0,f.version());assertThrows(Problem.class,()->s.updateFeedback(f.id(),new OpsWorkStore.FeedbackChange(0,"resolved","")));var next=s.updateFeedback(f.id(),new OpsWorkStore.FeedbackChange(0,"processing","正在核对"));assertEquals(1,next.version());var conflict=assertThrows(Problem.class,()->s.updateFeedback(f.id(),new OpsWorkStore.FeedbackChange(0,"resolved","已修正")));assertEquals(409,conflict.status());s.updateFeedback(f.id(),new OpsWorkStore.FeedbackChange(1,"resolved","已修正，等待版本发布"));var loaded=store();assertEquals("resolved",loaded.feedback().getFirst().status());assertEquals(3,loaded.audit().size());}
 @Test void proposalsRequireSourcesAndExplicitReview(){var s=store();assertThrows(Problem.class,()->s.createProposal(new OpsWorkStore.ProposalInput("米饭","饭","https://user:pass@example.com/data","有来源")));assertThrows(Problem.class,()->s.createProposal(new OpsWorkStore.ProposalInput("米饭","饭","file:///tmp/test","有来源")));assertThrows(Problem.class,()->s.createProposal(new OpsWorkStore.ProposalInput("米饭","饭","example.com","有来源")));assertTrue(s.proposals().isEmpty());var p=s.createProposal(new OpsWorkStore.ProposalInput("米饭","饭","https://example.com/food","来源说明，等待核对"));assertEquals("pending",p.status());assertThrows(Problem.class,()->s.review(p.id(),new OpsWorkStore.Review(0,"approved","")));var reviewed=s.review(p.id(),new OpsWorkStore.Review(0,"approved","仅审核资料，尚未接入计算目录"));assertEquals("approved",reviewed.status());assertEquals(1,store().proposals().getFirst().version());assertEquals(2,store().audit().size());assertThrows(Problem.class,()->s.review(p.id(),new OpsWorkStore.Review(0,"rejected","旧版本")));}
 @Test void archivesOnlyFinishedItemsAndPurgesTheirContent(){var s=store();var f=s.createFeedback(new OpsWorkStore.FeedbackInput("other","私密的反馈文字",true));assertThrows(Problem.class,()->s.archiveFeedback(f.id(),new OpsWorkStore.Version(0)));s.updateFeedback(f.id(),new OpsWorkStore.FeedbackChange(0,"resolved","已解决"));assertThrows(Problem.class,()->s.archiveFeedback(f.id(),new OpsWorkStore.Version(0)));s.archiveFeedback(f.id(),new OpsWorkStore.Version(1));assertTrue(store().feedback().isEmpty());var p=s.createProposal(new OpsWorkStore.ProposalInput("米饭","饭","https://example.com","来源"));assertThrows(Problem.class,()->s.archiveProposal(p.id(),new OpsWorkStore.Version(0)));s.review(p.id(),new OpsWorkStore.Review(0,"rejected","来源不足"));assertThrows(Problem.class,()->s.review(p.id(),new OpsWorkStore.Review(1,"approved","重审")));s.archiveProposal(p.id(),new OpsWorkStore.Version(1));assertTrue(store().proposals().isEmpty());assertEquals("archive",store().audit().getFirst().action());}
 @Test void invalidCategoriesMissingValuesAndUnknownIdsFailSafely(){var s=store();assertThrows(Problem.class,()->s.createFeedback(new OpsWorkStore.FeedbackInput(null,"ok",true)));assertThrows(Problem.class,()->s.createFeedback(new OpsWorkStore.FeedbackInput("other","x".repeat(2001),true)));assertThrows(Problem.class,()->s.createProposal(new OpsWorkStore.ProposalInput("x","","https://example.com",null)));assertEquals(404,assertThrows(Problem.class,()->s.updateFeedback("missing",new OpsWorkStore.FeedbackChange(0,"processing",""))).status());assertTrue(s.feedback().isEmpty());assertTrue(s.audit().isEmpty());}
 @Test void legacyWorkflowFileIsReadAndConvertedWithoutLosingFeedback()throws Exception{var mapper=new ObjectMapper();var item=new OpsWorkStore.Feedback("legacy-id",2,"other","旧反馈","processing","处理中","2026-11-14","2026-11-14");Files.writeString(dir.resolve("workflows.json"),mapper.writeValueAsString(new OpsWorkStore.State(List.of(item),List.of(),List.of())));var migrated=store();assertEquals("legacy-id",migrated.feedback().getFirst().id());migrated.updateFeedback("legacy-id",new OpsWorkStore.FeedbackChange(2,"resolved","已核对"));assertEquals("resolved",store().feedback().getFirst().status());assertTrue(Files.exists(dir.resolve("workflows-snapshot.json")));}
}
